def transform(grid):
    """Fill straight gaps between consecutive marker cells, horizontally and vertically."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    markers = {v for row in grid for v in row if v not in (0, 1, 7, 8)}
    # ARC examples use a single marker color and a distinct fill color.
    marker = next((v for v in markers), None)
    if marker is None:
        return out
    fill = next((v for v in range(10) if v not in (marker, 0, 1, 7, 8) and v not in markers), 3)
    # Color every background cell strictly between neighboring markers on a row/column.
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = fill
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(ys, ys[1:]):
            for r in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = fill
    return out

