def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    # The sparse non-background marker dots define horizontal and vertical strokes.
    marker = next(v for v, n in counts.items() if v != background and v != 3 and n < counts[background])
    out = [row[:] for row in grid]
    for r in range(h):
        xs = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(xs, xs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = 3
    for c in range(w):
